using MediatR;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Exceptions;using JTradeERP.Domain.MasterData;
namespace JTradeERP.Application.Features.MasterData.Customers.CreateCustomer;
public sealed class CreateCustomerHandler(IApplicationDbContext db):IRequestHandler<CreateCustomerCommand,CreateCustomerResponse>{public async Task<CreateCustomerResponse> Handle(CreateCustomerCommand r,CancellationToken ct){if(db.Customers.Any(x=>x.CustomerCode==r.CustomerCode.Trim()))throw new ConflictException("Customer code already exists.");var e=new Customer(r.CustomerCode,r.Name,r.BillingAddress,r.ShippingAddress,r.Phone,r.Email,r.TRN,r.CreditLimit);db.Add(e);await db.SaveChangesAsync(ct);return Map(e);}internal static CreateCustomerResponse Map(Customer e)=>new(e.Id,e.CustomerCode,e.Name,e.BillingAddress,e.ShippingAddress,e.Phone,e.Email,e.TRN,e.CreditLimit);}
